public class Main {
    public static void main(String[] args) {
        System.out.println("Hello, World!");

        // Teste da classe Produto
        Produto p1 = new Produto("Mouse", 59.90, 10);
        Produto p2 = new Produto("Teclado", 129.90);

        p1.exibirResumo();
        System.out.println("---");
        p2.exibirResumo();
        System.out.println("Adicionando 5 ao estoque do teclado...");
        p2.adicionarEstoque(5);
        p2.exibirResumo();
        System.out.println("Vendendo 3 mouses...");
        boolean venda = p1.vender(3);
        System.out.println("Venda realizada? " + venda);
        p1.exibirResumo();
        System.out.println("Tentando vender 20 teclados...");
        boolean venda2 = p2.vender(20);
        System.out.println("Venda realizada? " + venda2);
        p2.exibirResumo();
    }
}

public class Produto {
    private String nome;
    private double preco;
    private int estoque;

    // Construtor que define todos os atributos
    public Produto(String nome, double preco, int estoque) {
        this.nome = nome;
        this.preco = preco;
        this.estoque = estoque;
    }

    // Construtor que define apenas nome e preco, estoque inicial = 0
    public Produto(String nome, double preco) {
        this(nome, preco, 0);
    }

    // Método para adicionar ao estoque
    public void adicionarEstoque(int quantidade) {
        if (quantidade > 0) {
            this.estoque += quantidade;
        }
    }

    // Método para vender produtos
    public boolean vender(int quantidade) {
        if (quantidade > 0 && this.estoque >= quantidade) {
            this.estoque -= quantidade;
            return true;
        }
        return false;
    }

    // Método para exibir resumo do produto
    public void exibirResumo() {
        System.out.println("Produto: " + nome);
        System.out.println("Preço: R$ " + preco);
        System.out.println("Estoque: " + estoque);
    }
}
